#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <time.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <errno.h>

#define MAX_FAILURES 5
#define COOLDOWN_SEC 30
#define MAX_URL_LEN 2048
#define ALLOWED_SCHEMES_COUNT 2

typedef enum { CB_CLOSED, CB_OPEN, CB_HALF_OPEN } cb_state_t;

typedef struct {
    cb_state_t state;
    int failure_count;
    time_t last_failure_time;
    int half_open_attempts;
} circuit_breaker_t;

static circuit_breaker_t cb = { CB_CLOSED, 0, 0, 0 };

static const char *allowed_schemes[] = { "http", "https" };

static int validate_scheme(const char *url) {
    for (int i = 0; i < ALLOWED_SCHEMES_COUNT; i++) {
        size_t slen = strlen(allowed_schemes[i]);
        if (strncasecmp(url, allowed_schemes[i], slen) == 0 && url[slen] == ':') {
            return 1;
        }
    }
    return 0;
}

static int is_private_ipv4(uint32_t addr) {
    /* Check 10.0.0.0/8 */
    if ((addr & 0xFF000000) == 0x0A000000) return 1;
    /* Check 172.16.0.0/12 */
    if ((addr & 0xFFF00000) == 0xAC100000) return 1;
    /* Check 192.168.0.0/16 */
    if ((addr & 0xFFFF0000) == 0xC0A80000) return 1;
    /* Check 127.0.0.0/8 */
    if ((addr & 0xFF000000) == 0x7F000000) return 1;
    /* Check 169.254.0.0/16 link-local */
    if ((addr & 0xFFFF0000) == 0xA9FE0000) return 1;
    return 0;
}

static int resolve_and_check_host(const char *hostname) {
    struct addrinfo hints, *res, *rp;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    int rc = getaddrinfo(hostname, NULL, &hints, &res);
    if (rc != 0) return 0;

    for (rp = res; rp != NULL; rp = rp->ai_next) {
        struct sockaddr_in *sin = (struct sockaddr_in *)rp->ai_addr;
        uint32_t addr = ntohl(sin->sin_addr.s_addr);
        if (is_private_ipv4(addr)) {
            freeaddrinfo(res);
            return 0;
        }
    }
    freeaddrinfo(res);
    return 1;
}

static char *extract_hostname(const char *url) {
    const char *start = strstr(url, "://");
    if (!start) return NULL;
    start += 3;

    /* Skip userinfo if present */
    const char *at = strchr(start, '@');
    const char *slash = strchr(start, '/');
    if (at && (!slash || at < slash)) {
        start = at + 1;
    }

    size_t len = 0;
    const char *end = start;
    while (*end && *end != '/' && *end != ':' && *end != '?' && *end != '#') {
        end++;
        len++;
    }

    char *host = malloc(len + 1);
    if (!host) return NULL;
    memcpy(host, start, len);
    host[len] = '\0';
    return host;
}

static int cb_allow_request(void) {
    time_t now = time(NULL);
    switch (cb.state) {
        case CB_CLOSED:
            return 1;
        case CB_OPEN:
            if (difftime(now, cb.last_failure_time) >= COOLDOWN_SEC) {
                cb.state = CB_HALF_OPEN;
                cb.half_open_attempts = 0;
                return 1;
            }
            return 0;
        case CB_HALF_OPEN:
            return (cb.half_open_attempts < 1);
    }
    return 0;
}

static void cb_record_success(void) {
    cb.state = CB_CLOSED;
    cb.failure_count = 0;
}

static void cb_record_failure(void) {
    cb.failure_count++;
    cb.last_failure_time = time(NULL);
    if (cb.failure_count >= MAX_FAILURES) {
        cb.state = CB_OPEN;
    }
}

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    (void)userp;
    return size * nmemb;
}

/*
 * fetch_artifact_metadata: called during CI pipeline to retrieve
 * build artifact metadata from a registry URL provided in pipeline config.
 * The URL undergoes scheme validation and SSRF protection via DNS resolution check.
 */
int fetch_artifact_metadata(const char *registry_url, const char *artifact_path) {
    if (!registry_url || !artifact_path) return -1;

    char full_url[MAX_URL_LEN];
    int written = snprintf(full_url, sizeof(full_url), "%s/v2/%s/manifests/latest", registry_url, artifact_path);
    if (written < 0 || (size_t)written >= sizeof(full_url)) return -1;

    if (!validate_scheme(full_url)) {
        fprintf(stderr, "Invalid scheme in URL\n");
        return -1;
    }

    char *hostname = extract_hostname(full_url);
    if (!hostname) return -1;

    /* First resolution check - validate target is not internal */
    if (!resolve_and_check_host(hostname)) {
        fprintf(stderr, "Host resolves to private address, blocked\n");
        free(hostname);
        return -1;
    }
    free(hostname);

    if (!cb_allow_request()) {
        fprintf(stderr, "Circuit breaker is open, request denied\n");
        return -2;
    }

    CURL *curl = curl_easy_init();
    if (!curl) {
        cb_record_failure();
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, full_url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(curl, CURLOPT_MAXREDIRS, 5L);
    curl_easy_setopt(curl, CURLOPT_PROTOCOLS, CURLPROTO_HTTP | CURLPROTO_HTTPS);

    CURLcode res = curl_easy_perform(curl);
    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    curl_easy_cleanup(curl);

    if (res != CURLE_OK || http_code >= 500) {
        cb_record_failure();
        return -1;
    }

    cb_record_success();
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <registry_url> <artifact_path>\n", argv[0]);
        return 1;
    }
    return fetch_artifact_metadata(argv[1], argv[2]);
}
